/**
 * Prohibited definitive legal conclusions (anti-UPL guardrail).
 */
export const PROHIBITED_LEGAL_CONCLUSIONS = [
  /\bthis clause is illegal\b/i,
  /\bthis contract is (definitively )?invalid\b/i,
  /\bthis clause is (definitively )?unenforceable\b/i,
  /\byou are legally required to\b/i,
  /\byou will win\b/i,
  /\byou should sue\b/i,
  /\byou should (sign|reject) this\b/i,
  /\byou definitely have a case\b/i,
  /\bdocument [a-z0-9_-]+ (overrides|supersedes|cancels) document [a-z0-9_-]+\b/i,
  /\bthis (document|agreement|amendment) takes precedence\b/i,
  /\bthis amendment is (legally )?valid\b/i,
];

