export type ConsistencyCategory =
  (typeof CONSISTENCY_CATEGORIES)[keyof typeof CONSISTENCY_CATEGORIES];

/**
 * Checks whether text contains prohibited legal advice verdicts.
 */
export function containsProhibitedLegalConclusion(text: string): boolean {
  return PROHIBITED_LEGAL_CONCLUSIONS.some((pattern) => pattern.test(text));
}

